@Test
public void test() {
    BasePage page = new BasePage();
    PageReference pageRef = mock(PageReference.class);
    when(pageRef.getPage()).thenReturn(page);
    SearchClause clause = new SearchClause();
    clause.setComparator(SearchClause.Comparator.EQUALS);
    clause.setType(SearchClause.Type.ATTRIBUTE);
    clause.setProperty("username");
    TESTER.startComponentInPage(new UserSearchPanel.Builder(new ListModel<>(List.of(clause)), pageRef).required(true).enableSearch().build("content"));
    FormTester formTester = TESTER.newFormTester("content:searchFormContainer:search:multiValueContainer:innerForm");
    assertEquals("username", formTester.getForm().get("content:view:0:panel:container:property:textField").getDefaultModelObjectAsString());
    assertNull(formTester.getForm().get("content:view:0:panel:container:value:textField").getDefaultModelObject());
    formTester.setValue("content:view:0:panel:container:property:textField", "firstname");
    TESTER.executeAjaxEvent(formTester.getForm().get("content:view:0:panel:container:property:textField"), Constants.ON_KEYDOWN);
    formTester.setValue("content:view:0:panel:container:value:textField", "vincenzo");
    TESTER.executeAjaxEvent(formTester.getForm().get("content:view:0:panel:container:value:textField"), Constants.ON_KEYDOWN);
    Component searchButton = formTester.getForm().get("content:view:0:panel:container:operatorContainer:operator:search");
    TESTER.clickLink(searchButton);
    TESTER.executeAjaxEvent(searchButton.getPageRelativePath(), Constants.ON_CLICK);
    assertEquals("firstname", formTester.getForm().get("content:view:0:panel:container:property:textField").getDefaultModelObjectAsString());
    assertEquals("vincenzo", formTester.getForm().get("content:view:0:panel:container:value:textField").getDefaultModelObjectAsString());
}

